CREATE SCHEMA IF NOT EXISTS sales;
CREATE SCHEMA IF NOT EXISTS analytics;

CREATE TABLE public.customers (
  id integer PRIMARY KEY,
  email varchar(255) NOT NULL,
  full_name text NOT NULL,
  country text,
  created_at timestamptz NOT NULL
) DISTRIBUTED BY (id);
CREATE TABLE public.products (
  id integer PRIMARY KEY,
  sku varchar(32) NOT NULL,
  name text NOT NULL,
  price numeric(10,2) NOT NULL,
  in_stock boolean NOT NULL
) DISTRIBUTED BY (id);
CREATE TABLE public.orders (
  id bigint PRIMARY KEY,
  customer_id integer NOT NULL,
  status text NOT NULL,
  total numeric(10,2) NOT NULL,
  ordered_at timestamptz NOT NULL
) DISTRIBUTED BY (id);
CREATE TABLE public.order_items (
  id integer PRIMARY KEY,
  order_id bigint NOT NULL,
  product_id integer NOT NULL,
  quantity integer NOT NULL,
  unit_price numeric(10,2) NOT NULL
) DISTRIBUTED BY (id);


CREATE VIEW sales."orderLineSummary" AS
  SELECT o.status, count(*) AS orders, sum(o.total) AS revenue FROM public.orders o GROUP BY o.status;
CREATE MATERIALIZED VIEW analytics.daily_signups AS
  SELECT CAST(created_at AS date) AS day, count(*) AS signups FROM public.customers GROUP BY 1;

